<template><div><ListFilters :only-resources="['supplier-deliveries']" @query="pagination.page=1;load()"/><el-table :data="items" v-loading="loading" border><el-table-column prop="order_no" label="订单号"/><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="material_code" label="物料编码"/><el-table-column prop="quantity" label="发货数"/><el-table-column prop="carrier" label="承运商"/><el-table-column prop="tracking_no" label="运单号"/><el-table-column prop="expected_date" label="预计到货"/><el-table-column label="状态"><template slot-scope="s">{{{in_transit:'运输中/待收货',received:'已收货待质检',inspected:'已质检'}[s.row.status]||s.row.status}}</template></el-table-column><el-table-column label="操作"><template slot-scope="s"><el-button v-if="s.row.status==='in_transit'" type="text" @click="confirm(s.row)">确认实际收货</el-button></template></el-table-column></el-table><Pager :page="pagination" @change="p=>{pagination.page=p;load()}" @size="s=>{pagination.page=1;pagination.page_size=s;load()}"/></div></template>
<script>
import {api} from '../api/client';import ListFilters from './ListFilters.vue';import Pager from './Pager.vue';
export default {components:{ListFilters,Pager},data:()=>({items:[],pagination:{page:1,page_size:10,total:0},loading:false}),created(){this.load();},methods:{async load(){this.loading=true;try{const r=(await api.get('/supplier-deliveries',{params:this.pagination})).data;this.items=r.items;this.pagination.total=r.total;}catch(e){this.$message.error(e.response?.data?.detail||'交付记录加载失败');}finally{this.loading=false;}},async confirm(row){try{await this.$confirm(`请确认货物已经实际到达：${row.material_code} × ${row.quantity}。如数量不符，请先在收货单编辑数量。`,'确认实际收货');await api.post('/receipts/'+row.receipt_id+'/confirm');await this.load();this.$emit('refresh');this.$message.success('收货已确认，请继续进行质量检验');}catch(e){if(e!=='cancel')this.$message.error(e.response?.data?.detail||'确认失败');}}}};
</script>
